// Only implement required functions
struct BinaryTrie {
	using T = BinaryTrie;
	static const int B = 30;
	int cnt = 0, lazy = 0;
	T *c[2] = {};
	T*& ch(int b) {
		return c[b] ? c[b] : c[b] = new T();
	}
	int cc(int b) { return c[b] ? c[b]->cnt : 0; }
	void push(int i) {
		if (!lazy) return;
		if (i && (lazy >> (i - 1) & 1)) swap(c[0], c[1]);
		rep(b,0,2) if (c[b]) c[b]->lazy ^= lazy;
		lazy = 0;
	}
	void xorAll(int x) { lazy ^= x; }
	template<int ms = 0>
	int insert(int x, int i = B) {
		push(i);
		if (!i) return !ms && cnt ? 0 : (++cnt, 1);
		int b = x >> --i & 1;
		int add = ch(b)->insert<ms>(x, i);
		return cnt += add, add;
	}
	int erase(int x, int i = B) {
		if (!cnt) return 0;
		push(i);
		int sub = 1;
		if (i) {
			int b = x >> --i & 1;
			sub = c[b] ? c[b]->erase(x, i) : 0;
		}
		return cnt -= sub, sub;
	}
	int count(int x, int i = B) {
		if (!i || !cnt) return cnt;
		push(i);
		int b = x >> --i & 1;
		return c[b] ? c[b]->count(x, i) : 0;
	}
	int kth(int k, int i = B) {
		assert(0 <= k && k < cnt);
		if (!i) return 0;
		push(i);
		int n = cc(0), b = k >= n;
		return c[b]->kth(k - (b ? n : 0), i - 1)
			| (b << (i - 1));
	}
	int minxor(int xr = 0, int i = B) {
		if (!i || !cnt) return 0;
		push(i);
		int b = xr >> --i & 1;
		return cc(b) ? c[b]->minxor(xr, i) :
			c[!b]->minxor(xr, i) | 1 << i;
	}
	int maxxor(int xr = 0, int i = B) {
		if (!i || !cnt) return 0;
		push(i);
		int b = (xr >> --i & 1) ^ 1;
		return cc(b) ? c[b]->maxxor(xr, i) | 1 << i :
			c[!b]->maxxor(xr, i);
	}
	template<int sgn = 0>
	int countLG(int xr = 0, int k = 0, int i = B) {
		if (!i || !cnt) return 0;
		push(i);
		int b = (xr ^ k) >> --i & 1;
		return ((k >> i & 1) ^ sgn ? cc(!b) : 0) +
			(c[b] ? c[b]->countLG<sgn>(xr, k, i) : 0);
	}
	int mex(int xr = 0, int i = B) { // unique values
		if (!i) return 0;
		push(i);
		int b = xr >> --i & 1;
		if (cc(b) == 1 << i)
			return (c[!b] ? c[!b]->mex(xr, i) : 0) | 1 << i;
		return c[b] ? c[b]->mex(xr, i) : 0;
	}
	template<class F>
	void each(F f, int i = B, int x = 0) {
		if (!cnt) return;
		push(i);
		if (!i) f(x, cnt);
		else rep(b,0,2) if (c[b])
			c[b]->each(f, i - 1, x | (b << (i - 1)));
	}
	template<int ms = 0>
	void merge(T& o, int i = B) { // o safe to delete
		if (!o.cnt) return;
		push(i); o.push(i);
		if (i) rep(b,0,2) {
			if (!c[b]) swap(c[b], o.c[b]);
			else if (o.c[b]) c[b]->merge<ms>(*o.c[b], i - 1);
		}
		cnt = i ? cc(0) + cc(1) : (ms ? cnt + o.cnt : 1);
		o.cnt = 0;
	}
	~BinaryTrie() { delete c[0]; delete c[1]; }
};

array<vi, 3> cartesianTree(const vi& a) {
	vi p(sz(a), -1), l = p, r = p, s;
	rep(i,0,sz(a)) {
		int last = -1;
		while (!s.empty() && a[s.back()] > a[i]) {
			last = s.back();
			s.pop_back();
		}
		if (!s.empty()) {
			p[i] = s.back();
			r[s.back()] = i;
		}
		if (last != -1) p[last] = i;
		l[i] = last;
		s.push_back(i);
	}
	return {p, l, r};
}

struct FT {
	vector<ll> s;
	FT(int n) : s(n) {}
	void update(int pos, ll dif) { // a[pos] += dif
		for (; pos < sz(s); pos |= pos + 1) s[pos] += dif;
	}
	ll query(int pos) { // sum of values in [0, pos)
		ll res = 0;
		for (; pos > 0; pos &= pos - 1) res += s[pos-1];
		return res;
	}
	int lower_bound(ll sum) {// min pos st sum of [0, pos] >= sum
		// Returns n if no sum is >= sum, or -1 if empty sum is.
		if (sum <= 0) return -1;
		int pos = 0;
		for (int pw = 1 << 25; pw; pw >>= 1) {
			if (pos + pw <= sz(s) && s[pos + pw-1] < sum)
				pos += pw, sum -= s[pos-1];
		}
		return pos;
	}
};

struct FT2 {
	vector<vi> ys; vector<FT> ft;
	FT2(int limx) : ys(limx) {}
	void fakeUpdate(int x, int y) {
		for (; x < sz(ys); x |= x + 1) ys[x].push_back(y);
	}
	void init() {
		for (vi& v : ys) sort(all(v)), ft.emplace_back(sz(v));
	}
	int ind(int x, int y) {
		return (int)(lower_bound(all(ys[x]), y) - ys[x].begin()); }
	void update(int x, int y, ll dif) {
		for (; x < sz(ys); x |= x + 1)
			ft[x].update(ind(x, y), dif);
	}
	ll query(int x, int y) {
		ll sum = 0;
		for (; x; x &= x - 1)
			sum += ft[x-1].query(ind(x-1, y));
		return sum;
	}
};

