int calc() { ... } // compute current answer

vi mo(vector<pii> Q) {
	int L = 0, R = 0, blk = 350; // ~N/sqrt(Q)
	vi s(sz(Q)), res = s;
#define K(x) pii(x.first/blk, x.second ^ -(x.first/blk & 1))
	iota(all(s), 0);
	sort(all(s), [&](int s, int t){ return K(Q[s]) < K(Q[t]); });
	for (int qi : s) {
		pii q = Q[qi];
		while (L > q.first) add(--L, 0);
		while (R < q.second) add(R++, 1);
		while (L < q.first) del(L++, 0);
		while (R > q.second) del(--R, 1);
		res[qi] = calc();
	}
	return res;
}

vi moTree(vector<array<int, 2>> Q, vector<vi>& ed, int root=0){
	int N = sz(ed), pos[2] = {}, blk = 350; // ~N/sqrt(Q)
	vi s(sz(Q)), res = s, I(N), L(N), R(N), in(N), par(N);
	add(0, 0), in[0] = 1;
	auto dfs = [&](int x, int p, int dep, auto& f) -> void {
		par[x] = p;
		L[x] = N;
		if (dep) I[x] = N++;
		for (int y : ed[x]) if (y != p) f(y, x, !dep, f);
		if (!dep) I[x] = N++;
		R[x] = N;
	};
	dfs(root, -1, 0, dfs);
#define K(x) pii(I[x[0]] / blk, I[x[1]] ^ -(I[x[0]] / blk & 1))
	iota(all(s), 0);
	sort(all(s), [&](int s, int t){ return K(Q[s]) < K(Q[t]); });
	for (int qi : s) rep(end,0,2) {
		int &a = pos[end], b = Q[qi][end], i = 0;
#define step(c) { if (in[c]) { del(a, end); in[a] = 0; } \
                  else { add(c, end); in[c] = 1; } a = c; }
		while (!(L[b] <= L[a] && R[a] <= R[b]))
			I[i++] = b, b = par[b];
		while (a != b) step(par[a]);
		while (i--) step(I[i]);
		if (end) res[qi] = calc();
	}
	return res;
}

struct DynCon {
	RollbackUF uf;
	vector<vector<pii>> st;
	map<pii, int> eds;
	int n, q, t = 0;
	DynCon(int n, int q) : uf(n), n(n), q(1) {
		while (this->q < max(q, 1)) this->q *= 2;
		st.resize(2 * this->q);
	}
	void add(int l, int r, pii e) {
		for (l += q, r += q; l < r; l /= 2, r /= 2) {
			if (l & 1) st[l++].push_back(e);
			if (r & 1) st[--r].push_back(e);
		}
	}
	void toggle(int u, int v) {
		assert(t < q);
		if (u > v) swap(u, v);
		pii e{u, v};
		if (eds.count(e)) {
			add(eds[e], t, e);
			eds.erase(e);
		} else eds[e] = t;
		++t;
	}
	void query() {
		assert(t < q);
		st[q + t++].push_back({-1, -1});
	}
	void rec(int i, vi& res) {
		int t0 = uf.time();
		for (auto [a, b] : st[i]) if (a >= 0) uf.join(a, b);
		for (auto [a, b] : st[i])
			if (a < 0) res.push_back(n - uf.time() / 2);
		if (i < q) rec(2 * i, res), rec(2 * i + 1, res);
		uf.rollback(t0);
	}
	vi ans() {
		for (auto [e, s] : eds) add(s, t, e);
		vi res;
		rec(1, res);
		return res;
	}
};

