void ropeExample() {
	int a[] = {0, 1, 2, 3, 4};
	rope<int> r(a, a + 5); // or rope<int>(n, value)
	rope<int> saved = r; // cheap snapshot
	r.insert(2, rope<int>(3, 10)); // insert before index 2
	r.erase(1, 3); // remove [1, 4): {0, 10, 2, 3, 4}
	r.replace(0, 9); // set index 0 (also r[0] = 9)
	rope<int> sub = r.substr(1, 2); // {10, 2}
	r += sub; // concatenate; r.push_back(x) also works
	vector<int> v(all(r)); // materialize in O(N)
	assert(v == (vi{9, 10, 2, 3, 4, 10, 2}));
	assert(saved[0] == 0 && saved.size() == 5);
	rope<char> s("abc"); // string variant
	s.insert(1, "XY"); // aXYbc
}

struct Tree {
	typedef int T;
	static constexpr T unit = INT_MIN;
	T f(T a, T b) { return max(a, b); } // (any associative fn)
	vector<T> s; int n;
	Tree(int n = 0, T def = unit) : s(2*n, def), n(n) {}
	void update(int pos, T val) {
		for (s[pos += n] = val; pos /= 2;)
			s[pos] = f(s[pos * 2], s[pos * 2 + 1]);
	}
	T query(int b, int e) { // query [b, e)
		T ra = unit, rb = unit;
		for (b += n, e += n; b < e; b /= 2, e /= 2) {
			if (b % 2) ra = f(ra, s[b++]);
			if (e % 2) rb = f(s[--e], rb);
		}
		return f(ra, rb);
	}
};

struct Node {
	using V = int;
	using U = int;
	using T = Node;
	static constexpr V id = INT_MIN;
	static constexpr V def = 0;
	static constexpr U idU = 0;
	V binop(V a, V b) { return max(a, b); }
	V applyUpdate(U u, V v) { return v + u; }
	U mergeUpdate(U oldU, U nw) { return oldU + nw; }
	T *lt = 0, *rt = 0;
	V val = def;
	U lazy = idU;
	void updateNode(int, int, U u) {
		lazy = mergeUpdate(lazy, u);
		val = applyUpdate(u, val);
	}
	void push(int l, int r) {
		if (!lt) {
			lt = new T();
			rt = new T();
		}
		int mid = l + (r - l) / 2;
		lt->updateNode(l, mid, lazy);
		rt->updateNode(mid + 1, r, lazy);
		lazy = idU;
	}
	void update(int l, int r, int ql, int qr, U u) {
		if (qr < l || r < ql) return;
		if (ql <= l && r <= qr) {
			updateNode(l, r, u);
			return;
		}
		push(l, r);
		int mid = l + (r - l) / 2;
		lt->update(l, mid, ql, qr, u);
		rt->update(mid + 1, r, ql, qr, u);
		val = binop(lt->val, rt->val);
	}
	void set(int l, int r, int i, V v) {
		if (i < l || r < i) return;
		if (l == r) { val = v; lazy = idU; return; }
		push(l, r);
		int mid = l + (r - l) / 2;
		if (i <= mid) lt->set(l, mid, i, v);
		else rt->set(mid + 1, r, i, v);
		val = binop(lt->val, rt->val);
	}
	V query(int l, int r, int ql, int qr) {
		if (qr < l || r < ql) return id;
		if (ql <= l && r <= qr) return val;
		push(l, r);
		int mid = l + (r - l) / 2;
		return binop(lt->query(l, mid, ql, qr),
			rt->query(mid + 1, r, ql, qr));
	}
	~Node() { delete lt; delete rt; }
};

struct RangeQuery {
	typedef int T;
	static constexpr T unit = 0;
	T f(T a, T b) { return a + b; }
	vector<vector<T>> stor;
	vector<T> a;
	int n = 0;
	RangeQuery() {}
	RangeQuery(const vector<T>& v) { build(v); }
	void fill(int l, int r, int ind) {
		if (ind < 0) return;
		int m = (l + r) / 2;
		T prod = unit;
		rep(i,m,r) stor[i][ind] = prod = f(prod, a[i]);
		prod = unit;
		for (int i = m; i-- > l;)
			stor[i][ind] = prod = f(a[i], prod);
		fill(l, m, ind - 1);
		fill(m, r, ind - 1);
	}
	void build(const vector<T>& v) {
		int lg = 0, m = max(sz(v), 1);
		while ((1 << lg) < m) lg++;
		a.assign(1 << lg, unit);
		rep(i,0,sz(v)) a[i] = v[i];
		n = 1 << lg;
		stor.assign(n, vector<T>(max(lg, 1)));
		fill(0, n, lg - 1);
	}
	T query(int l, int r) { // [l, r)
		assert(l < r);
		if (l == --r) return a[l];
		int t = 31 - __builtin_clz(l ^ r);
		return f(stor[l][t], stor[r][t]);
	}
};

template<class T>
struct SubMatrix {
	vector<vector<T>> p;
	SubMatrix(vector<vector<T>>& v) {
		int R = sz(v), C = sz(v[0]);
		p.assign(R+1, vector<T>(C+1));
		rep(r,0,R) rep(c,0,C)
			p[r+1][c+1] = v[r][c] + p[r][c+1] + p[r+1][c] - p[r][c];
	}
	T sum(int u, int l, int d, int r) {
		return p[d][r] - p[d][l] - p[u][r] + p[u][l];
	}
};

struct Node {
	using V = ll;
	using U = ll;
	static constexpr V id = 0;
	static constexpr V def = 0;
	static constexpr U idU = 0;
	V binop(V a, V b) { return a + b; }
	V applyUpdate(U u, V v, int len) { return v + u * len; }
	U mergeUpdate(U oldU, U nw) { return oldU + nw; }
	Node *l = 0, *r = 0;
	V val = def, agg = def;
	int y, c = 1;
	U lazy = idU;
	Node(V val = def) : val(val), agg(val), y(rand()) {}
	void apply(U u) {
		val = applyUpdate(u, val, 1);
		agg = applyUpdate(u, agg, c);
		lazy = mergeUpdate(lazy, u);
	}
	void push() {
		if (lazy == idU) return;
		if (l) l->apply(lazy);
		if (r) r->apply(lazy);
		lazy = idU;
	}
	void pull();
};

int cnt(Node* n) { return n ? n->c : 0; }
Node::V query(Node* n) { return n ? n->agg : Node::id; }
void Node::pull() {
	c = cnt(l) + cnt(r) + 1;
	agg = binop(binop(query(l), val), query(r));
}

template<class F> void each(Node* n, F f) {
	if (!n) return;
	n->push(); each(n->l, f);
	f(n->val); each(n->r, f);
}
pair<Node*, Node*> split(Node* n, int k) { // left gets k nodes
	if (!n) return {};
	n->push();
	if (cnt(n->l) >= k) { // "n->val >= k" for lower_bound(k)
		auto [L,R] = split(n->l, k);
		n->l = R;
		n->pull();
		return {L, n};
	} else {
		auto [L,R] = split(n->r,k - cnt(n->l) - 1); // and just "k"
		n->r = L;
		n->pull();
		return {n, R};
	}
}

Node* merge(Node* l, Node* r) {
	if (!l) return r;
	if (!r) return l;
	if (l->y > r->y) {
		l->push();
		l->r = merge(l->r, r);
		return l->pull(), l;
	} else {
		r->push();
		r->l = merge(l, r->l);
		return r->pull(), r;
	}
}

Node* ins(Node* t, Node* n, int pos) {
	auto [l,r] = split(t, pos);
	return merge(merge(l, n), r);
}

// Example application: move the range [l, r) to index k
void move(Node*& t, int l, int r, int k) {
	Node *a, *b, *c;
	tie(a,b) = split(t, l); tie(b,c) = split(b, r - l);
	if (k <= l) t = merge(ins(a, b, k), c);
	else t = merge(a, ins(c, b, k - r));
}

struct UF {
	vi e;
	UF(int n) : e(n, -1) {}
	bool sameSet(int a, int b) { return find(a) == find(b); }
	int size(int x) { return -e[find(x)]; }
	int find(int x) { return e[x] < 0 ? x : e[x] = find(e[x]); }
	bool join(int a, int b) {
		a = find(a), b = find(b);
		if (a == b) return false;
		if (e[a] > e[b]) swap(a, b);
		e[a] += e[b]; e[b] = a;
		return true;
	}
};

struct RollbackUF {
	vi e; vector<pii> st;
	RollbackUF(int n) : e(n, -1) {}
	int size(int x) { return -e[find(x)]; }
	int find(int x) { return e[x] < 0 ? x : find(e[x]); }
	int time() { return sz(st); }
	void rollback(int t) {
		for (int i = time(); i --> t;)
			e[st[i].first] = st[i].second;
		st.resize(t);
	}
	bool join(int a, int b) {
		a = find(a), b = find(b);
		if (a == b) return false;
		if (e[a] > e[b]) swap(a, b);
		st.push_back({a, e[a]});
		st.push_back({b, e[b]});
		e[a] += e[b]; e[b] = a;
		return true;
	}
};

struct RandomHash {
	static uint64_t mix(uint64_t x) {
		x += 0x9e3779b97f4a7c15;
		x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
		x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
		return x ^ (x >> 31);
	}
	size_t operator()(uint64_t x) const {
		static const uint64_t seed = chrono::steady_clock::now()
			.time_since_epoch().count();
		return mix(x + seed);
	}
};
