struct WaveletTree {
	int n;
	vi vals;
	vector<vi> b;
	WaveletTree(const vi& a) : n(sz(a)), vals(a) {
		sort(all(vals));
		vals.erase(unique(all(vals)), vals.end());
		b.resize(4 * sz(vals));
		if (n) build(a, 1, 0, sz(vals));
	}
	void build(const vi& a, int v, int lo, int hi) {
		if (hi-lo <= 1) return;
		int m = lo + (hi-lo)/2;
		vi c[2];
		b[v].resize(sz(a) + 1);
		rep(i,0,sz(a)) {
			int left = a[i] < vals[m];
			b[v][i+1] = b[v][i] + left;
			c[!left].push_back(a[i]);
		}
		build(c[0], 2*v, lo, m);
		build(c[1], 2*v+1, m, hi);
	}
	int kth(int l, int r, int k) const {
		assert(0 <= l && l <= r && r <= n);
		assert(0 <= k && k < r-l);
		int v = 1, lo = 0, hi = sz(vals);
		while (hi-lo > 1) {
			int m = lo + (hi-lo)/2, lb = b[v][l], rb = b[v][r];
			if (k < rb-lb) {
				l = lb; r = rb; hi = m; v *= 2;
			} else {
				k -= rb-lb; l -= lb; r -= rb;
				lo = m; v = 2*v+1;
			}
		}
		return vals[lo];
	}
	int countLess(int l, int r, ll x) const {
		assert(0 <= l && l <= r && r <= n);
		if (l == r) return 0;
		int v = 1, lo = 0, hi = sz(vals), ans = 0;
		while (hi-lo > 1) {
			int m = lo + (hi-lo)/2, lb = b[v][l], rb = b[v][r];
			if (x <= vals[m]) {
				l = lb; r = rb; hi = m; v *= 2;
			} else {
				ans += rb-lb; l -= lb; r -= rb;
				lo = m; v = 2*v+1;
			}
		}
		return ans + (vals[lo] < x ? r-l : 0);
	}
	int count(int l, int r, ll lo, ll hi) const {
		assert(lo <= hi);
		return countLess(l, r, hi) - countLess(l, r, lo);
	}
};

template<ll mod = 1000000007>
vector<ll> berlekampMassey(vector<ll> s) {
	int n = sz(s), L = 0, m = 0;
	vector<ll> C(n), B(n), T;
	C[0] = B[0] = 1;

	ll b = 1;
	rep(i,0,n) { ++m;
		ll d = s[i] % mod;
		rep(j,1,L+1) d = (d + C[j] * s[i - j]) % mod;
		if (!d) continue;
		T = C; ll coef = d * modpow<mod>(b, mod-2) % mod;
		rep(j,m,n) C[j] = (C[j] - coef * B[j - m]) % mod;
		if (2 * L > i) continue;
		L = i + 1 - L; B = T; b = d; m = 0;
	}

	C.resize(L + 1); C.erase(C.begin());
	for (ll& x : C) x = (mod - x) % mod;
	return C;
}

double det(vector<vector<double>>& a) {
	int n = sz(a); double res = 1;
	rep(i,0,n) {
		int b = i;
		rep(j,i+1,n) if (fabs(a[j][i]) > fabs(a[b][i])) b = j;
		if (i != b) swap(a[i], a[b]), res *= -1;
		res *= a[i][i];
		if (res == 0) return 0;
		rep(j,i+1,n) {
			double v = a[j][i] / a[i][i];
			if (v != 0) rep(k,i+1,n) a[j][k] -= v * a[i][k];
		}
	}
	return res;
}

typedef complex<double> C;
typedef vector<double> vd;
void fft(vector<C>& a) {
	int n = sz(a), L = 31 - __builtin_clz(n);
	static vector<complex<long double>> R(2, 1);
	static vector<C> rt(2, 1);  // (^ 10% faster if double)
	for (static int k = 2; k < n; k *= 2) {
		R.resize(n); rt.resize(n);
		auto x = polar(1.0L, acos(-1.0L) / k);
		rep(i,k,2*k) rt[i] = R[i] = i&1 ? R[i/2] * x : R[i/2];
	}
	vi rev(n);
	rep(i,0,n) rev[i] = (rev[i / 2] | (i & 1) << L) / 2;
	rep(i,0,n) if (i < rev[i]) swap(a[i], a[rev[i]]);
	for (int k = 1; k < n; k *= 2)
		for (int i = 0; i < n; i += 2 * k) rep(j,0,k) {
			C z = rt[j+k] * a[i+j+k]; // (25% faster if hand-rolled)
			a[i + j + k] = a[i + j] - z;
			a[i + j] += z;
		}
}
vd conv(const vd& a, const vd& b) {
	if (a.empty() || b.empty()) return {};
	vd res(sz(a) + sz(b) - 1);
	int L = 32 - __builtin_clz(sz(res)), n = 1 << L;
	vector<C> in(n), out(n);
	copy(all(a), begin(in));
	rep(i,0,sz(b)) in[i].imag(b[i]);
	fft(in);
	for (C& x : in) x *= x;
	rep(i,0,n) out[i] = in[-i & (n - 1)] - conj(in[i]);
	fft(out);
	rep(i,0,sz(res)) res[i] = imag(out[i]) / (4 * n);
