ull ord(ull a, ull p) {
	a %= p;
	ull t = p - 1;
	for (ull q : pfactors(t))
		while (t % q == 0 && modpow(a, t / q, p) == 1)
			t /= q;
	return t;
}
ull primitiveRoot(ull p) {
	if (p == 2) return 1;
	auto divs = pfactors(p - 1);
	for (ull g = 2; g < p; g++) {
		bool ok = 1;
		for (ull q : divs)
			if (modpow(g, (p - 1) / q, p) == 1) {
				ok = 0; break;
			}
		if (ok) return g;
	}
	return 0;
}

