		siz[u] = 1;
		for (int v : g[u]) if (v != p && !banned[v])
			siz[u] += dfsSz(v, u);
		return siz[u];
	}
	int dfsCen(int u, int p, int n) {
		for (int v : g[u]) if (v != p && !banned[v])
			if (siz[v] > n / 2) return dfsCen(v, u, n);
		return u;
	}
	template<class F>
	void decomp(int u, F f) {
		int c = dfsCen(u, -1, dfsSz(u, -1));
		f(c);
		banned[c] = true;
		for (int v : g[c]) if (!banned[v]) decomp(v, f);
	}
};

