// Arithmetic mod 2^64-1. 2x slower than mod 2^64 and more
// code, but works on evil test data (e.g. Thue-Morse, where
// ABBA... and BAAB... of length 2^10 hash the same mod 2^64).
// "typedef ull H;" instead if you think test data is random,
// or work mod 10^9+7 if the Birthday paradox is not a problem.
typedef uint64_t ull;
struct H {
	ull x; H(ull x=0) : x(x) {}
	H operator+(H o) { return x + o.x + (x + o.x < x); }
	H operator-(H o) { return *this + ~o.x; }
	H operator*(H o) { auto m = (__uint128_t)x * o.x;
		return H((ull)m) + (ull)(m >> 64); }
	ull get() const { return x + !~x; }
	bool operator==(H o) const { return get() == o.get(); }
	bool operator<(H o) const { return get() < o.get(); }
};
static const H C = (ll)1e11+3; // (order ~ 3e9; random also ok)

struct HashInterval {
	vector<H> ha, pw;
	HashInterval(string& str) : ha(sz(str)+1), pw(ha) {
		pw[0] = 1;
		rep(i,0,sz(str))
			ha[i+1] = ha[i] * C + str[i],
			pw[i+1] = pw[i] * C;
	}
	H hashInterval(int a, int b) { // hash [a, b)
		return ha[b] - ha[a] * pw[b - a];
	}
};

vector<H> getHashes(string& str, int length) {
	if (sz(str) < length) return {};
	H h = 0, pw = 1;
	rep(i,0,length)
		h = h * C + str[i], pw = pw * C;
	vector<H> ret = {h};
	rep(i,length,sz(str)) {
		ret.push_back(h = h * C + str[i] - pw * str[i-length]);
	}
	return ret;
}

H hashString(string& s){H h{}; for(char c:s) h=h*C+c;return h;}

vi pi(const string& s) {
	vi p(sz(s));
	rep(i,1,sz(s)) {
		int g = p[i-1];
		while (g && s[i] != s[g]) g = p[g-1];
		p[i] = g + (s[i] == s[g]);
	}
	return p;
}

vi match(const string& s, const string& pat) {
	vi p = pi(pat + '\0' + s), res;
	rep(i,sz(p)-sz(s),sz(p))
		if (p[i] == sz(pat)) res.push_back(i - 2 * sz(pat));
	return res;
}

array<vi, 2> manacher(const string& s) {
	int n = sz(s);
	array<vi,2> p = {vi(n+1), vi(n)};
	rep(z,0,2) for (int i=0,l=0,r=0; i < n; i++) {
		int t = r-i+!z;
		if (i<r) p[z][i] = min(t, p[z][l+t]);
		int L = i-p[z][i], R = i+p[z][i]-!z;
		while (L>=1 && R+1<n && s[L-1] == s[R+1])
			p[z][i]++, L--, R++;
		if (R>r) l=L, r=R;
	}
	return p;
}

int minRotation(string s) {
	int a=0, N=sz(s); s += s;
	rep(b,0,N) rep(k,0,N) {
		if (a+k == b || s[a+k] < s[b+k]) {b += max(0, k-1); break;}
		if (s[a+k] > s[b+k]) { a = b; break; }
	}
	return a;
}

struct SuffixArray {
	vi sa, lcp, rank, lg;
	vector<vi> st;
	SuffixArray(string s, int lim = 256) {
		s.push_back(0); int n = sz(s), k = 0, a, b;
		vi x(n), y(n), ws(max(n, lim));
		rep(i,0,n) x[i] = (unsigned char)s[i];
		sa = lcp = y, iota(all(sa), 0);
		for (int j = 0, p = 0; p < n; j = max(1, j * 2), lim = p) {
			p = j, iota(all(y), n - j);
			rep(i,0,n) if (sa[i] >= j) y[p++] = sa[i] - j;
			fill(all(ws), 0);
			rep(i,0,n) ws[x[i]]++;
			rep(i,1,lim) ws[i] += ws[i - 1];
			for (int i = n; i--;) sa[--ws[x[y[i]]]] = y[i];
			swap(x, y), p = 1, x[sa[0]] = 0;
			rep(i,1,n) a = sa[i - 1], b = sa[i], x[b] =
				(y[a] == y[b] && y[a + j] == y[b + j]) ? p - 1 : p++;
		}
		for (int i = 0, j; i < n - 1; lcp[x[i++]] = k)
			for (k && k--, j = sa[x[i] - 1];
					s[i + k] == s[j + k]; k++);
		rank = x;
		buildRMQ();
	}
	void buildRMQ() {
		int n = sz(lcp);
		lg.assign(n + 1, 0);
		rep(i,2,n+1) lg[i] = lg[i / 2] + 1;
		st.assign(lg[n] + 1, vi(n));
		st[0] = lcp;
		rep(k,1,sz(st)) rep(i,0,n - (1 << k) + 1)
			st[k][i] = min(st[k-1][i], st[k-1][i + (1<<(k-1))]);
	}
	int rmq(int l, int r) { // inclusive
		if (l > r) return INT_MAX;
		int k = lg[r - l + 1];
		return min(st[k][l], st[k][r - (1 << k) + 1]);
	}
	int getLCP(int i, int j) {
		if (i == j) return sz(sa) - 1 - i; // ignore sentinel
		int ri = rank[i], rj = rank[j];
		if (ri > rj) swap(ri, rj);
		return rmq(ri + 1, rj);
	}
	// compare s[a..a+lena) vs s[b..b+lenb); -1 / 0 / 1
	int cmpSubstr(int a, int lena, int b, int lenb,
			const string& s) {
		int common = min(getLCP(a, b), min(lena, lenb));
		if (common == min(lena, lenb)) {
			if (lena == lenb) return 0;
			return lena < lenb ? -1 : 1;
		}
		return (unsigned char)s[a + common] <
			(unsigned char)s[b + common] ? -1 : 1;
	}
};

struct SuffixTree {
	enum { N = 200010, ALPHA = 26 }; // N ~ 2*maxlen+10
	int toi(char c) { return c - 'a'; }
	string a; // v = cur node, q = cur position
	int t[N][ALPHA],l[N],r[N],p[N],s[N],v=0,q=0,m=2;

	void ukkadd(int i, int c) { suff:
		if (r[v]<=q) {
			if (t[v][c]==-1) { t[v][c]=m;  l[m]=i;
				p[m++]=v; v=s[v]; q=r[v];  goto suff; }
			v=t[v][c]; q=l[v];
		}
		if (q==-1 || c==toi(a[q])) q++; else {
			l[m+1]=i;  p[m+1]=m;  l[m]=l[v];  r[m]=q;
			p[m]=p[v];  t[m][c]=m+1;  t[m][toi(a[q])]=v;
			l[v]=q;  p[v]=m;  t[p[m]][toi(a[l[m]])]=m;
			v=s[p[m]];  q=l[m];
			while (q<r[m]) { v=t[v][toi(a[q])];  q+=r[v]-l[v]; }
			if (q==r[m])  s[m]=v;  else s[m]=m+2;
			q=r[v]-(q-r[m]);  m+=2;  goto suff;
		}
	}

	SuffixTree(string a) : a(a) {
		fill(r,r+N,sz(a));
		memset(s, 0, sizeof s);
		memset(t, -1, sizeof t);
		fill(t[1],t[1]+ALPHA,0);
		s[0] = 1; l[0] = l[1] = -1; r[0] = r[1] = p[0] = p[1] = 0;
		rep(i,0,sz(a)) ukkadd(i, toi(a[i]));
	}

	// example: find longest common substring (uses ALPHA = 28)
	pii best;
	int lcs(int node, int i1, int i2, int olen) {
		if (l[node] <= i1 && i1 < r[node]) return 1;
		if (l[node] <= i2 && i2 < r[node]) return 2;
		int mask = 0, len = node ? olen + (r[node] - l[node]) : 0;
		rep(c,0,ALPHA) if (t[node][c] != -1)
			mask |= lcs(t[node][c], i1, i2, len);
		if (mask == 3)
			best = max(best, {len, r[node] - len});
		return mask;
	}
	static pii LCS(string s, string t) {
		SuffixTree st(s + (char)('z' + 1) + t + (char)('z' + 2));
		st.lcs(0, sz(s), sz(s) + 1 + sz(t), 0);
		return st.best;
	}
};

vi Z(const string& S) {
	vi z(sz(S));
	int l = -1, r = -1;
	rep(i,1,sz(S)) {
		z[i] = i >= r ? 0 : min(r - i, z[i - l]);
		while (i + z[i] < sz(S) && S[i + z[i]] == S[z[i]])
			z[i]++;
		if (i + z[i] > r)
			l = i, r = i + z[i];
	}
	return z;
}

using ull = unsigned long long;
template<int N> struct Big : array<unsigned, N> {
	static_assert(N > 0);
	static constexpr unsigned base = 1000000000;
	Big(ull x = 0) : array<unsigned, N>{} {
		for (int i = N; i-- && x; x /= base)
			(*this)[i] = unsigned(x % base);
	}
	explicit Big(string_view s) : Big() {
		assert(!s.empty());
		for (char c : s) assert('0' <= c && c <= '9');
		int end = sz(s);
		for (int i = N; i-- && end > 0;) {
			int start = max(0, end-9);
			unsigned x = 0;
			rep(j,start,end) x = x*10 + unsigned(s[j]-'0');
			(*this)[i] = x, end = start;
		}
	}
	string toString() const {
		int i = 0;
		while (i < N-1 && !(*this)[i]) i++;
		string s = to_string((*this)[i]);
		while (++i < N) {
			string t = to_string((*this)[i]);
			s += string(9-sz(t), '0') + t;
		}
		return s;
	}
	Big& operator+=(const Big& b) {
		unsigned carry = 0;
		for (int i = N; i--;) {
			unsigned t = (*this)[i] + b[i] + carry;
			(*this)[i] = t % base, carry = t / base;
		}
		return *this;
	}
	Big operator-() const {
		Big r = *this;
		for (unsigned& x : r) x = base-1-x;
		return r += 1;
	}
	Big& operator-=(const Big& b) { return *this += -b; }
	friend Big operator+(Big a, const Big& b) { return a += b; }
	friend Big operator-(Big a, const Big& b) { return a -= b; }
	Big& operator*=(unsigned b) {
		ull carry = 0;
		for (int i = N; i--;) {
			ull t = ull((*this)[i]) * b + carry;
			(*this)[i] = unsigned(t % base), carry = t / base;
		}
		return *this;
	}
	unsigned div(unsigned b) {
		assert(b);
		ull rem = 0;
		rep(i,0,N) {
			ull t = rem * base + (*this)[i];
			(*this)[i] = unsigned(t / b), rem = t % b;
		}
		return unsigned(rem);
	}
	Big& operator/=(unsigned b) { div(b); return *this; }
	friend Big operator*(Big a, unsigned b) { return a *= b; }
	friend Big operator*(unsigned b, Big a) { return a *= b; }
	friend Big operator/(Big a, unsigned b) { return a /= b; }
	friend unsigned operator%(Big a, unsigned b) {
		return a.div(b);
	}
};

