// Row-minima indices for totally monotone f(x,y). O(N + M)
template<class Fn>
vi min_smawk_rec(Fn& f, const vi& row, vi col) {
	int n = sz(row);
	if (!n) return {};
	vi red;
	for (int c : col) {
		while (sz(red) &&
			f(row[sz(red)-1], c) < f(row[sz(red)-1], red.back()))
			red.pop_back();
		if (sz(red) < n) red.pb(c);
	}
	col = move(red);

	vi odd;
	for (int i = 1; i < n; i += 2) odd.pb(row[i]);
	vi oddans = min_smawk_rec(f, odd, col), ans(n);
	rep(i,0,sz(odd)) ans[2*i+1] = oddans[i];
	for (int i = 0, j = 0; i < n; i += 2) {
		ans[i] = col[j];
		int last = i+1 < n ? ans[i+1] : col.back();
		while (col[j] != last) {
			j++;
			if (f(row[i], col[j]) < f(row[i], ans[i]))
				ans[i] = col[j];
		}
	}
	return ans;
}
template<class Fn>
vi min_smawk(Fn f, int r, int c) {
	vi row(r), col(c);
	iota(all(row), 0), iota(all(col), 0);
	return min_smawk_rec(f, row, col);
}

// Min-plus c[k]=min_{i+j=k}(a[i]+b[j]), convex b. O(N+M)
template<class V>
vector<V> min_plus_smawk(const vector<V>& a,
		const vector<V>& b) {
	int n = sz(a), m = sz(b);
	assert(n && m);
	auto f = [&](int r, int c) -> tuple<int,V,int> {
		if (r < c) return {1, V{}, c};
		if (r-c >= m) return {1, V{}, -c};
		return {0, a[c]+b[r-c], 0};
	};
	vi cols = min_smawk(f, n+m-1, n);
	vector<V> d(n+m-1);
	rep(r,0,n+m-1) d[r] = a[cols[r]]+b[r-cols[r]];
	return d;
}

// Min-plus conv for concave b. O(N log M + M)
template<class V>
vector<V> min_plus_concave_one(const vector<V>& a,
		const vector<V>& b) {
	int n = sz(a), m = sz(b), z = n+m-1;
	assert(n && m);
	vector<V> c(z, numeric_limits<V>::max());
	auto solve = [&](int l, int r, bool rev) {
		auto val = [&](int j, int k) {
			if (rev) j = n-1-j, k = z-1-k;
			return a[j]+b[k-j];
		};
#define better(i,j,k) val(i,k) <= val(j,k)
		auto improve = [&](int u, int v, int l, int r) {
			while (r-l > 1) {
				int m = (l+r)/2;
				(better(u,v,m) ? r : l) = m;
			}
			return l;
		};
		vector<array<int,2>> stk;
		for (int i = l, k = l, s = -1; k < r; i++, k++) {
			while (s >= 0 && i < n &&
					better(i, stk[s][0], stk[s][1])) {
				stk.pop_back(), s--;
			}
			if (i < n) {
				int t = s < 0 ? r-1
					: improve(stk[s][0], i, k-1, stk[s][1]);
				if (t >= k) stk.pb({i,t}), s++;
			}
			int out = rev ? z-1-k : k;
			c[out] = min(c[out], val(stk[s][0], k));
			if (stk[s][1] == k) stk.pop_back(), s--;
		}
	};

	solve(0,m,0), solve(0,m,1);
	for (int k = m; k < z-m; k += m+1)
		solve(k+1,k+m+1,0), solve(z-k-m,z-k,1);
#undef better
	return c;
}

struct Node {
	using V = int;
	using U = int;
	using T = Node;
	static constexpr V id = INT_MIN;
	static constexpr V def = 0;
	static constexpr U idU = 0;
	V binop(V a, V b) { return max(a, b); }
	V applyUpdate(U u, V v) { return v + u; }
	U mergeUpdate(U oldU, U nw) { return oldU + nw; }
	T *lt = 0, *rt = 0;
	V val = def;
	U lazy = idU;
	void updateNode(int, int, U u) {
		lazy = mergeUpdate(lazy, u);
		val = applyUpdate(u, val);
	}
	void push(int l, int r) {
		int mid = l + (r - l) / 2;
		lt = new T(lt ? *lt : T());
		rt = new T(rt ? *rt : T());
		lt->updateNode(l, mid, lazy);
		rt->updateNode(mid + 1, r, lazy);
		lazy = idU;
	}
	T* update(int l, int r, int ql, int qr, U u) {
		if (qr < l || r < ql) return this;
		T* n = new T(*this);
		if (ql <= l && r <= qr) {
			n->updateNode(l, r, u);
			return n;
		}
		n->push(l, r);
		int mid = l + (r - l) / 2;
		n->lt = n->lt->update(l, mid, ql, qr, u);
		n->rt = n->rt->update(mid + 1, r, ql, qr, u);
		n->val = binop(n->lt->val, n->rt->val);
		return n;
	}
	T* set(int l, int r, int i, V v) {
		if (i < l || r < i) return this;
		T* n = new T(*this);
		if (l == r) { n->val = v; n->lazy = idU; return n; }
		n->push(l, r);
		int mid = l + (r - l) / 2;
		if (i <= mid) n->lt = n->lt->set(l, mid, i, v);
		else n->rt = n->rt->set(mid + 1, r, i, v);
		n->val = binop(n->lt->val, n->rt->val);
		return n;
	}
	V query(int l, int r, int ql, int qr) {
		if (qr < l || r < ql) return id;
		if (ql <= l && r <= qr) return val;
		int mid = l + (r - l) / 2;
		T a = lt ? *lt : T();
		T b = rt ? *rt : T();
		a.updateNode(l, mid, lazy);
		b.updateNode(mid + 1, r, lazy);
		return binop(a.query(l, mid, ql, qr),
			b.query(mid + 1, r, ql, qr));
	}
};

