struct Angle {
	pp p;
	int t;
	Angle(pp p, int t=0) : p(p), t(t) {}
	Angle operator-(Angle b) const { return {p-b.p, t}; }
	int half() const {
		assert(p != pp());
		return p.imag() < 0 || (p.imag() == 0 && p.real() < 0);
	}
	Angle t90() const {
		return {perp(p), t + (half() && p.real() >= 0)};
	}
	Angle t180() const { return {-p, t + half()}; }
	Angle t360() const { return {p, t + 1}; }
};
bool operator<(Angle a, Angle b) {
	// Add norm(a.p), norm(b.p) to break ties by distance.
	if (a.t != b.t) return a.t < b.t;
	if (a.half() != b.half()) return a.half() < b.half();
	return crossp(a.p, b.p) > 0;
}

// Given two points, this calculates the smallest angle between
// them, i.e., the angle that covers the defined line segment.
pair<Angle, Angle> segmentAngles(Angle a, Angle b) {
	if (b < a) swap(a, b);
	return (b < a.t180() ?
	        make_pair(a, b) : make_pair(b, a.t360()));
}
Angle operator+(Angle a, Angle b) { // point a + vector b
	Angle r(a.p + b.p, a.t);
	if (a.t180() < r) r.t--;
	return r.t180() < a ? r.t360() : r;
}
Angle angleDiff(Angle a, Angle b) { // angle b - angle a
	int tu = b.t - a.t; a.t = b.t;
	return {{dotp(a.p,b.p), crossp(a.p,b.p)}, tu - (b < a)};
}

bool circleInter(pp a,pp b,double r1,double r2,pair<pp, pp>* out) {
	if (a == b) { assert(r1 != r2); return false; }
	pp vec = b - a;
	double d2 = norm(vec), sum = r1+r2, dif = r1-r2,
	       p = (d2 + r1*r1 - r2*r2)/(d2*2), h2 = r1*r1 - p*p*d2;
	if (sum*sum < d2 || dif*dif > d2) return false;
	pp mid = a + vec*p, per = perp(vec) * sqrt(fmax(0, h2) / d2);
	*out = {mid + per, mid - per};
	return true;
}

vector<pp> circleLine(pp c, double r, pp a, pp b) {
	pp ab = b - a, p = a + ab * dotp(c-a, ab) / norm(ab);
	double s = orient(a, b, c), h2 = r*r - s*s / norm(ab);
	if (h2 < 0) return {};
	if (h2 == 0) return {p};
	pp h = ab / abs(ab) * sqrt(h2);
	return {p - h, p + h};
}

double angleBetween(pp p, pp q) {
	return atan2(crossp(p, q), dotp(p, q));
}
double circlePoly(pp c, double r, vector<pp> ps) {
	auto tri = [&](pp p, pp q) {
		auto r2 = r * r / 2;
		pp d = q - p;
		if (p == q) return 0.0;
		auto a = dotp(d, p)/norm(d), b = (norm(p)-r*r)/norm(d);
		auto det = a * a - b;
		if (det <= 0) return angleBetween(p, q) * r2;
		auto s = max(0., -a-sqrt(det)), t = min(1., -a+sqrt(det));
		if (t < 0 || 1 <= s) return angleBetween(p, q) * r2;
		pp u = p + d * s, v = q + d * (t-1);
		return angleBetween(p,u) * r2 + crossp(u,v)/2
		     + angleBetween(v,q) * r2;
	};
	auto sum = 0.0;
	rep(i,0,sz(ps))
		sum += tri(ps[i] - c, ps[(i + 1) % sz(ps)] - c);
	return sum;
}

vector<pair<pp, pp>> tangents(pp c1, double r1, pp c2, double r2) {
	pp d = c2 - c1;
	double dr = r1 - r2, d2 = norm(d), h2 = d2 - dr * dr;
	if (d2 == 0 || h2 < 0)  return {};
	vector<pair<pp, pp>> out;
	for (double sign : {-1, 1}) {
		pp v = (d * dr + perp(d) * sqrt(h2) * sign) / d2;
		out.push_back({c1 + v * r1, c2 + v * r2});
	}
	if (h2 == 0) out.pop_back();
	return out;
}

