pair<pp, pp> closest(vector<pp> v) {
	assert(sz(v) > 1);
	sort(all(v), PointLess{});
	vector<pp> tmp(sz(v));
	double best = INFINITY;
	pair<pp, pp> ret{v[0], v[1]};
	auto upd = [&](pp a, pp b) {
		if (double d = norm(a - b); d < best)
			best = d, ret = {a, b};
	};
	auto byY = [](pp a, pp b) { return a.imag() < b.imag(); };
	auto rec = [&](auto&& self, int l, int r) -> void {
		if (best == 0) return;
		if (r - l <= 3) {
			rep(i,l,r) rep(j,i+1,r) upd(v[i], v[j]);
			sort(v.begin() + l, v.begin() + r, byY);
			return;
		}
		int m = (l + r) / 2;
		double x = v[m].real();
		self(self, l, m), self(self, m, r);
		if (best == 0) return;
		auto a = v.begin() + l, b = v.begin() + m;
		auto c = v.begin() + r;
		merge(a, b, b, c, tmp.begin(), byY);
		copy_n(tmp.begin(), r - l, a);
		int k = 0;
		rep(i,l,r) {
			double dx = v[i].real() - x;
			if (dx * dx < best) tmp[k++] = v[i];
		}
		rep(i,0,k) rep(j,i+1,k) {
			double dy = tmp[j].imag() - tmp[i].imag();
			if (dy * dy >= best) break;
			upd(tmp[i], tmp[j]);
		}
	};
	rec(rec, 0, sz(v));
	return ret;
}

vector<pp> convexHull(vector<pp> pts) {
	if (sz(pts) <= 1) return pts;
	sort(all(pts), PointLess{});
	vector<pp> h(sz(pts)+1);
	int s = 0, t = 0;
	for (int it = 2; it--; s = --t, reverse(all(pts)))
		for (pp p : pts) {
			while (t >= s + 2 && orient(h[t-2], h[t-1], p) <= 0) t--;
			h[t++] = p;
		}
	return {h.begin(), h.begin() + t - (t == 2 && h[0] == h[1])};
}

template<class F>
void delaunay(vector<pp>& ps, F trifun) {
	if (sz(ps) == 3) { int d = (orient(ps[0], ps[1], ps[2]) < 0);
		trifun(0,1+d,2-d); }
	vector<P3> p3;
	for (pp p : ps) p3.emplace_back(p.real(), p.imag(), norm(p));
	if (sz(ps) > 3) for(auto t:hull3d(p3)) if ((p3[t.b]-p3[t.a]).
			cross(p3[t.c]-p3[t.a]).dot(P3(0,0,1)) < 0)
		trifun(t.a, t.c, t.b);
}

typedef struct Quad* Q;
typedef long double lll;
pp arb(DBL_MAX, DBL_MAX); // not equal to any other point

struct Quad {
	Q rot, o; pp p = arb; bool mark;
	pp& F() { return r()->p; }
	Q& r() { return rot->rot; }
	Q prev() { return rot->o->rot; }
	Q next() { return r()->prev(); }
} *H;

bool circ(pp p, pp a, pp b, pp c) { // is p in the circumcircle?
	lll p2 = norm(p), A = norm(a)-p2,
	    B = norm(b)-p2, C = norm(c)-p2;
	return orient(p,a,b)*C + orient(p,b,c)*A
	     + orient(p,c,a)*B > 0;
}
Q makeEdge(pp orig, pp dest) {
	Q r = H ? H : new Quad{new Quad{new Quad{new Quad{0}}}};
	H = r->o; r->r()->r() = r;
	rep(i,0,4) r = r->rot, r->p = arb, r->o = i & 1 ? r : r->r();
	r->p = orig; r->F() = dest;
	return r;
}
void splice(Q a, Q b) {
	swap(a->o->rot->o, b->o->rot->o); swap(a->o, b->o);
}
Q connect(Q a, Q b) {
	Q q = makeEdge(a->F(), b->p);
	splice(q, a->next());
	splice(q->r(), b);
	return q;
}

pair<Q,Q> rec(const vector<pp>& s) {
	if (sz(s) <= 3) {
		Q a = makeEdge(s[0], s[1]), b = makeEdge(s[1], s.back());
		if (sz(s) == 2) return { a, a->r() };
		splice(a->r(), b);
		auto side = orient(s[0], s[1], s[2]);
		Q c = side ? connect(b, a) : 0;
		return {side < 0 ? c->r() : a, side < 0 ? c : b->r() };
	}

#define H(e) e->F(), e->p
#define valid(e) (orient(e->F(), H(base)) > 0)
	Q A, B, ra, rb;
	int half = sz(s) / 2;
	tie(ra, A) = rec({all(s) - half});
	tie(B, rb) = rec({sz(s) - half + all(s)});
	while ((orient(B->p, H(A)) < 0 && (A = A->next())) ||
	       (orient(A->p, H(B)) > 0 && (B = B->r()->o)));
	Q base = connect(B->r(), A);
	if (A->p == ra->p) ra = base->r();
	if (B->p == rb->p) rb = base;

#define DEL(e, init, dir) Q e = init->dir; if (valid(e)) \
		while (circ(e->dir->F(), H(base), e->F())) { \
			Q t = e->dir; \
			splice(e, e->prev()); \
			splice(e->r(), e->r()->prev()); \
			e->o = H; H = e; e = t; \
		}
	for (;;) {
		DEL(LC, base->r(), o);  DEL(RC, base, prev());
		if (!valid(LC) && !valid(RC)) break;
		if (!valid(LC) || (valid(RC) && circ(H(RC), H(LC))))
			base = connect(RC, base->r());
		else
			base = connect(base->r(), LC->r());
	}
	return { ra, rb };
}

vector<pp> triangulate(vector<pp> pts) {
	sort(all(pts), PointLess{});
	assert(unique(all(pts)) == pts.end());
	if (sz(pts) < 2) return {};
	Q e = rec(pts).first;
	vector<Q> q = {e};
	int qi = 0;
	while (orient(e->o->F(), e->F(), e->p) < 0) e = e->o;
#define ADD { Q c = e; do { c->mark = 1; pts.push_back(c->p); \
	q.push_back(c->r()); c = c->next(); } while (c != e); }
	ADD; pts.clear();
	while (qi < sz(q)) if (!(e = q[qi++])->mark) ADD;
	return pts;
}

const double HP_EPS = 1e-9, HP_INF = 1e9;

struct HP {
	pp s, e, d;
	double ang;
	HP() {}
	HP(pp a, pp b) : s(a), e(b), d((b-a)/abs(b-a)),
		ang(arg(d)) {}
	bool out(pp p) { return crossp(d, p - s) < -HP_EPS; }
	bool operator<(HP o) const { return ang < o.ang; }
};

pp hpI(HP a, HP b) {
	return a.s + a.d * (crossp(b.s-a.s, b.d) /
		crossp(a.d, b.d));
}

vector<pp> halfPlaneInter(vector<HP> h) {
	pp box[] = {pp(HP_INF, HP_INF), pp(-HP_INF, HP_INF),
		pp(-HP_INF, -HP_INF), pp(HP_INF, -HP_INF)};
	rep(i,0,4) h.push_back(HP(box[i], box[(i+1)%4]));
	sort(all(h));
	deque<HP> dq;
	for (HP L : h) {
		while (sz(dq) > 1 &&
			L.out(hpI(dq.back(), dq[sz(dq)-2])))
			dq.pop_back();
		while (sz(dq) > 1 && L.out(hpI(dq[0], dq[1])))
			dq.pop_front();
		if (!dq.empty() &&
			(L.d == dq.back().d || L.d == -dq.back().d ||
			crossp(L.d, dq.back().d) == 0)) {
			if (dotp(L.d, dq.back().d) < 0) return {};
			if (L.out(dq.back().s)) dq.pop_back();
			else continue;
		}
		dq.push_back(L);
	}
	while (sz(dq) > 2 &&
		dq[0].out(hpI(dq.back(), dq[sz(dq)-2])))
		dq.pop_back();
	while (sz(dq) > 2 &&
		dq.back().out(hpI(dq[0], dq[1])))
		dq.pop_front();
	if (sz(dq) < 3) return {};
	vector<pp> res;
	rep(i,0,sz(dq))
		res.push_back(hpI(dq[i], dq[(i+1)%sz(dq)]));
	vector<pp> out;
	for (pp p : res) {
		if (out.empty() || abs(p - out.back()) > HP_EPS)
			out.push_back(p);
	}
	if (sz(out) >= 2 && abs(out[0]-out.back()) <= HP_EPS)
		out.pop_back();
	if (sz(out) < 3) return {};
	if (polygonArea2(out) == 0) return {};
	return out;
}

array<pp, 2> hullDiameter(vector<pp> S) {
	assert(!S.empty());
	int n = sz(S), j = n < 2 ? 0 : 1;
	auto best = norm(S[0]-S[0]);
	array<pp, 2> res{S[0], S[0]};
	rep(i,0,j)
		for (;; j = (j + 1) % n) {
			if (auto d2 = norm(S[i] - S[j]); d2 > best)
				best = d2, res = {S[i], S[j]};
			if (crossp(S[(j + 1) % n] - S[j], S[i + 1] - S[i]) >= 0)
				break;
		}
	return res;
}

bool inPolygon(vector<pp> &p, pp a, bool strict = true) {
	int cnt = 0, n = sz(p);
	rep(i,0,n) {
		pp q = p[(i + 1) % n];
		if (onSegment(p[i], q, a)) return !strict;
		//or: if (segDist(p[i], q, a) <= eps) return !strict;
		int above = (a.imag()<p[i].imag()) - (a.imag()<q.imag());
		cnt ^= above * orient(a, p[i], q) > 0;
	}
	return cnt;
}

typedef double T;
const T INF = numeric_limits<T>::max();

bool on_x(pp a, pp b) { return a.real() < b.real(); }
bool on_y(pp a, pp b) { return a.imag() < b.imag(); }

struct Node {
	pp pt; // if this is a leaf, the single point in it
	T x0 = INF, x1 = -INF, y0 = INF, y1 = -INF; // bounds
	Node *first = 0, *second = 0;

	T distance(pp p) { // min squared distance to a point
		T x = (p.real() < x0 ? x0 : p.real() > x1 ? x1 : p.real());
		T y = (p.imag() < y0 ? y0 : p.imag() > y1 ? y1 : p.imag());
		return norm(pp(x,y) - p);
	}

	Node(vector<pp>&& vp) : pt(vp[0]) {
		for (pp p : vp) {
			x0 = min(x0, p.real()); x1 = max(x1, p.real());
			y0 = min(y0, p.imag()); y1 = max(y1, p.imag());
		}
		if (vp.size() > 1) {
			// split on x if width >= height (not ideal...)
			sort(all(vp), x1 - x0 >= y1 - y0 ? on_x : on_y);
			// divide by taking half the array for each child (not
			// best performance with many duplicates in the middle)
			int half = sz(vp)/2;
			first = new Node({vp.begin(), vp.begin() + half});
			second = new Node({vp.begin() + half, vp.end()});
		}
	}
};

struct KDTree {
	Node* root;
	KDTree(const vector<pp>& vp) : root(new Node({all(vp)})) {}

	pair<T, pp> search(Node *node, pp p) {
		if (!node->first) {
			// uncomment if we should not find the point itself:
			// if (p == node->pt) return {INF, pp()};
			return make_pair(norm(p - node->pt), node->pt);
		}

		Node *f = node->first, *s = node->second;
		T bfirst = f->distance(p), bsec = s->distance(p);
		if (bfirst > bsec) swap(bsec, bfirst), swap(f, s);

		// search closest side first, other side if needed
		auto best = search(f, p);
		if (bsec < best.first) {
			auto other = search(s, p);
			if (other.first < best.first) best = other;
		}
		return best;
	}

	// find nearest point to a point, and its squared distance
	// Requires a nonempty point set.
	pair<T, pp> nearest(pp p) {
		return search(root, p);
	}
};

pp linearTransformation(pp p0, pp p1, pp q0, pp q1, pp r) {
	return q0 + (r-p0) * (q1-q0) / (p1-p0);
}

double lineDist(pp a, pp b, pp p) {
	return crossp(b-a, p-a)/dist(b-a);
}

snippets.description:
Line-convex polygon intersection. The polygon must be ccw and have no collinear points.
\texttt{lineHull(line, poly)} returns a pair describing the intersection of a line with the polygon:
$(-1, -1)$ if no collision;
$(i, -1)$ if touching the corner $i$;
$(i, i)$ if along side $(i, i+1)$;
$(i, j)$ if crossing sides $(i, i+1)$ and $(j, j+1)$.
In the last case, if a corner $i$ is crossed, this is treated as happening on side $(i, i+1)$.
The points are returned in the same order as the line hits the polygon.
\texttt{extrVertex} returns the point of a hull with the max projection onto a line.

snippets.code:
#define cmp(i,j) sgn(crossp(perp(dir), poly[(i)%n]-poly[(j)%n]))
#define extr(i) cmp(i + 1, i) >= 0 && cmp(i, i - 1 + n) < 0
int extrVertex(vector<pp>& poly, pp dir) {
	int n = sz(poly), lo = 0, hi = n;
	if (extr(0)) return 0;
	while (lo + 1 < hi) {
		int m = (lo + hi) / 2;
		if (extr(m)) return m;
		int ls = cmp(lo + 1, lo), ms = cmp(m + 1, m);
		(ls < ms || (ls == ms && ls == cmp(lo, m)) ? hi : lo) = m;
	}
	return lo;
}

#define cmpL(i) sgn(orient(a, poly[i], b))
array<int, 2> lineHull(pp a, pp b, vector<pp>& poly) {
	int endA = extrVertex(poly, perp(a - b));
	int endB = extrVertex(poly, perp(b - a));
	if (cmpL(endA) < 0 || cmpL(endB) > 0)
		return {-1, -1};
	array<int, 2> res;
	rep(i,0,2) {
		int lo = endB, hi = endA, n = sz(poly);
		while ((lo + 1) % n != hi) {
			int m = ((lo + hi + (lo < hi ? 0 : n)) / 2) % n;
			(cmpL(m) == cmpL(endB) ? lo : hi) = m;
		}
		res[i] = (lo + !cmpL(hi)) % n;
		swap(endA, endB);
	}
	if (res[0] == res[1]) return {res[0], -1};
	if (!cmpL(res[0]) && !cmpL(res[1]))
		switch ((res[0] - res[1] + sz(poly) + 1) % sz(poly)) {
			case 0: return {res[0], res[0]};
			case 2: return {res[1], res[1]};
		}
	return res;
}

