pair<int, pp> lineInter(pp s1, pp e1, pp s2, pp e2) {
	auto d = crossp(e1 - s1, e2 - s2);
	if (d == 0) // if parallel
		return {-(orient(s1, e1, s2) == 0), pp(0, 0)};
	auto p = orient(s2, e1, e2), q = orient(s2, e2, s1);
	return {1, (s1 * p + e1 * q) / d};
}

pp lineProj(pp a, pp b, pp p, bool refl=false) {
	pp v = b - a;
	auto d = crossp(v, p-a) * (1+refl);
	return p - perp(v)*d/norm(v);
}

struct MEdge { double d; int a, b; };
vector<MEdge> manhattanMST(vector<pp> ps) {
	vi id(sz(ps));
	iota(all(id), 0);
	vector<MEdge> edges;
	rep(k,0,4) {
		sort(all(id), [&](int i, int j) {
		     return (ps[i]-ps[j]).real() < (ps[j]-ps[i]).imag();});
		map<double, int> sweep;
		for (int i : id) {
			for (auto it = sweep.lower_bound(-ps[i].imag());
				        it != sweep.end(); sweep.erase(it++)) {
				int j = it->second;
				pp d = ps[i] - ps[j];
				if (d.imag() > d.real()) break;
				edges.push_back({d.imag() + d.real(), i, j});
			}
			sweep[-ps[i].imag()] = i;
		}
		for (pp& p : ps)
			p = k & 1 ? pp(-p.real(), p.imag())
			            : pp(p.imag(), p.real());
	}
	return edges;
}

pair<pp, double> mec(vector<pp> ps) {
	if (ps.empty()) return {pp(), 0};
	shuffle(all(ps), mt19937(time(0)));
	pp o = ps[0];
	double r = 0, EPS = 1 + 1e-8;
	rep(i,0,sz(ps)) if (abs(o - ps[i]) > r * EPS) {
		o = ps[i], r = 0;
		rep(j,0,i) if (abs(o - ps[j]) > r * EPS) {
			o = (ps[i] + ps[j]) / 2.0;
			r = abs(o - ps[i]);
			rep(k,0,j) if (abs(o - ps[k]) > r * EPS) {
				o = ccCenter(ps[i], ps[j], ps[k]);
				r = abs(o - ps[i]);
			}
		}
	}
	return {o, r};
}

bool onSegment(pp s, pp e, pp p) {
	return orient(p, s, e) == 0 && dotp(s - p, e - p) <= 0;
}

typedef double dd;
typedef complex<dd> pp;

int sgn(double x) { return (x > 0) - (x < 0); }
double dotp(pp a, pp b) {
	return a.real()*b.real() + a.imag()*b.imag();
}
double crossp(pp a, pp b) {
	return a.real()*b.imag() - a.imag()*b.real();
}
double orient(pp a, pp b, pp c) {
	return crossp(b-a, c-a);
}
pp perp(pp p) {
	return {-p.imag(), p.real()};
}
double dist(pp p) { return abs(p); }
struct PointLess {
	bool operator()(pp a, pp b) const {
		return make_pair(a.real(), a.imag()) <
		       make_pair(b.real(), b.imag());
	}
};

struct Point3D {
	double x, y, z;
	explicit Point3D(double x=0, double y=0, double z=0) :
		x(x), y(y), z(z) {}
	bool operator<(Point3D p) const {
		return tie(x, y, z) < tie(p.x, p.y, p.z); }
	bool operator==(Point3D p) const {
		return tie(x, y, z) == tie(p.x, p.y, p.z); }
	Point3D operator+(Point3D p) const {
		return Point3D(x+p.x, y+p.y, z+p.z); }
	Point3D operator-(Point3D p) const {
		return Point3D(x-p.x, y-p.y, z-p.z); }
	Point3D operator*(double d) const {
		return Point3D(x*d, y*d, z*d); }
	Point3D operator/(double d) const {
		return Point3D(x/d, y/d, z/d); }
	double dot(Point3D p) const { return x*p.x + y*p.y + z*p.z; }
	Point3D cross(Point3D p) const {
		return Point3D(y*p.z-z*p.y, z*p.x-x*p.z, x*p.y-y*p.x);
	}
	double dist2() const { return x*x + y*y + z*z; }
	double dist() const { return sqrt(dist2()); }
	//Azimuthal angle (longitude) to x-axis in interval [-pi, pi]
	double phi() const { return atan2(y, x); }
	//Zenith angle (latitude) to the z-axis in interval [0, pi]
	double theta() const { return atan2(sqrt(x*x+y*y),z); }
	Point3D unit() const { return *this/dist(); } //makes dist()=1
	//returns unit vector normal to *this and p
	Point3D normal(Point3D p) const { return cross(p).unit(); }
	//returns point rotated 'angle' radians ccw around axis
	Point3D rotate(double angle, Point3D axis) const {
		double s = sin(angle), c = cos(angle);
		Point3D u = axis.unit();
		return u*dot(u)*(1-c) + (*this)*c - cross(u)*s;
	}
};

bool inHull(const vector<pp>& l, pp p, bool strict = true) {
	if (l.empty()) return false;
	int a = 1, b = sz(l) - 1, r = !strict;
	if (sz(l) < 3) return r && onSegment(l[0], l.back(), p);
	if (sideOf(l[0], l[a], l[b]) > 0) swap(a, b);
	if (sideOf(l[0], l[a], p) >= r || sideOf(l[0], l[b], p)<= -r)
		return false;
	while (abs(a - b) > 1) {
		int c = (a + b) / 2;
		(sideOf(l[0], l[c], p) > 0 ? b : a) = c;
	}
	return sgn(orient(l[a], l[b], p)) < r;
}

double polygonArea2(const vector<pp>& v) {
	if (v.empty()) return 0;
	double a = 0;
	rep(i,1,sz(v)-1) a += crossp(v[i]-v[0], v[i+1]-v[0]);
	return a;
}

pp polygonCenter(const vector<pp>& v) {
	pp res(0, 0); double A = 0;
	rep(i,1,sz(v)-1) {
		pp p = v[i]-v[0], q = v[i+1]-v[0];
		double a = crossp(p, q);
		res += (p + q) * a;
		A += a;
	}
	return v[0] + res / A / 3.0;
}

vector<pp> polygonCut(const vector<pp>& poly, pp s, pp e) {
	vector<pp> res;
	rep(i,0,sz(poly)) {
		pp cur = poly[i], prev = i ? poly[i-1] : poly.back();
		auto a = orient(s, e, cur), b = orient(s, e, prev);
		if ((a < 0) != (b < 0))
			res.push_back(cur + (prev - cur) * (a / (a - b)));
		if (a < 0)
			res.push_back(cur);
	}
	return res;
}

double rat(pp a, pp b) {
	return b.real() ? a.real()/b.real() : a.imag()/b.imag();
}
double polyUnion(vector<vector<pp>>& poly) {
	double ret = 0;
	rep(i,0,sz(poly)) rep(v,0,sz(poly[i])) {
		pp A = poly[i][v], B = poly[i][(v + 1) % sz(poly[i])];
		vector<pair<double, int>> segs = {{0, 0}, {1, 0}};
		rep(j,0,sz(poly)) if (i != j) {
			rep(u,0,sz(poly[j])) {
				pp C = poly[j][u], D = poly[j][(u + 1) % sz(poly[j])];
				int sc = sideOf(A, B, C), sd = sideOf(A, B, D);
				if (sc != sd) {
					double sa = orient(C, D, A), sb = orient(C, D, B);
					if (min(sc, sd) < 0)
						segs.emplace_back(sa / (sa - sb), sgn(sc - sd));
				} else if (!sc && !sd && j<i && sgn(dotp(B-A, D-C))>0){
					segs.emplace_back(rat(C - A, B - A), 1);
					segs.emplace_back(rat(D - A, B - A), -1);
				}
			}
		}
		sort(all(segs));
		for (auto& s : segs) s.first = min(max(s.first, 0.0), 1.0);
		double sum = 0;
		int cnt = segs[0].second;
		rep(j,1,sz(segs)) {
			if (!cnt) sum += segs[j].first - segs[j - 1].first;
			cnt += segs[j].second;
		}
		ret += crossp(A, B) * sum;
	}
	return ret / 2;
}

template<class V, class L>
double signedPolyVolume(const V& p, const L& trilist) {
	double v = 0;
	for (auto i : trilist) v += p[i.a].cross(p[i.b]).dot(p[i.c]);
	return v / 6;
}

double segDist(pp s, pp e, pp p) {
	if (s==e) return abs(p-s);
	auto d = norm(e-s), t = min(d,max(.0,dotp(p-s, e-s)));
	return abs((p-s)*d-(e-s)*t)/d;
}

