vector<pp> segInter(pp a, pp b, pp c, pp d) {
	auto oa = orient(c, d, a), ob = orient(c, d, b),
	     oc = orient(a, b, c), od = orient(a, b, d);
	// Checks if intersection is single non-endpoint point.
	if (sgn(oa) * sgn(ob) < 0 && sgn(oc) * sgn(od) < 0)
		return {(a * ob - b * oa) / (ob - oa)};
	set<pp, PointLess> s;
	if (onSegment(c, d, a)) s.insert(a);
	if (onSegment(c, d, b)) s.insert(b);
	if (onSegment(a, b, c)) s.insert(c);
	if (onSegment(a, b, d)) s.insert(d);
	return {all(s)};
}

int sideOf(pp s, pp e, pp p) { return sgn(orient(s, e, p)); }

int sideOf(pp s, pp e, pp p, double eps) {
	auto a = crossp(e-s, p-s);
	double l = dist(e-s)*eps;
	return (a > l) - (a < -l);
}

double sphericalDistance(double f1, double t1,
		double f2, double t2, double radius) {
	array<double,3> a = {sin(t1)*cos(f1),
		sin(t1)*sin(f1), cos(t1)};
	array<double,3> b = {sin(t2)*cos(f2),
		sin(t2)*sin(f2), cos(t2)};
	double d = 0, s = 0;
	rep(i,0,3) {
		d += (b[i]-a[i])*(b[i]-a[i]);
		s += (b[i]+a[i])*(b[i]+a[i]);
	}
	return radius*2*atan2(sqrt(d), sqrt(s));
}
